import{_ as e,o as r,c as a,a0 as l}from"./chunks/framework.n1c-_RXi.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"core/assets/material/material.md","filePath":"core/assets/material/material.md"}'),o={name:"core/assets/material/material.md"};function s(n,t,d,i,c,f){return r(),a("div",null,[...t[0]||(t[0]=[l('<h6 id="version-0-7-1" tabindex="-1">version: 0.7.1 <a class="header-anchor" href="#version-0-7-1" aria-label="Permalink to &quot;version: 0.7.1&quot;">​</a></h6><hr><h2 id="material" tabindex="-1">Material <a class="header-anchor" href="#material" aria-label="Permalink to &quot;Material&quot;">​</a></h2><h2 id="material-1" tabindex="-1">Material <a class="header-anchor" href="#material-1" aria-label="Permalink to &quot;Material&quot;">​</a></h2><p><code>Material</code> is a plain data struct holding the PBR (glTF 2.0 metallic-roughness) look of a mesh surface: colour factors, metalness/roughness, alpha mode, up to five texture slots, per-texture UV sets, and a name. A CharacterController skin system copies the mesh material, retints <code>baseColorFactor</code> per team, and writes it back with <code>Mesh::setMaterial</code>.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Type</th><th style="text-align:left;">Property</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./../../maths/vector4/vector4.html"><strong>Vector4</strong></a></td><td style="text-align:left;"><a href="./material-base-color-factor.html"><strong>baseColorFactor</strong></a></td><td style="text-align:left;">Linear-space RGBA colour multiplied with <code>baseColorTexture</code>. Defaults to <code>(1, 1, 1, 1)</code>.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/float" target="_blank" rel="noreferrer"><strong>float</strong></a></td><td style="text-align:left;"><a href="./material-metallic-factor.html"><strong>metallicFactor</strong></a></td><td style="text-align:left;">Metalness multiplier (<code>0.0</code> dielectric, <code>1.0</code> metallic). Defaults to <code>1.0</code>.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/float" target="_blank" rel="noreferrer"><strong>float</strong></a></td><td style="text-align:left;"><a href="./material-roughness-factor.html"><strong>roughnessFactor</strong></a></td><td style="text-align:left;">Roughness multiplier (<code>0.0</code> glossy, <code>1.0</code> diffuse). Defaults to <code>1.0</code>.</td></tr><tr><td style="text-align:left;"><a href="./../../../incomplete-docs.html"><strong>MaterialAlphaMode</strong></a></td><td style="text-align:left;"><a href="./material-alpha-mode.html"><strong>alphaMode</strong></a></td><td style="text-align:left;">How combined alpha is rendered (<code>AUTO</code>, <code>ALPHA_OPAQUE</code>, <code>MASK</code>, <code>BLEND</code>). Defaults to <code>AUTO</code>.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/float" target="_blank" rel="noreferrer"><strong>float</strong></a></td><td style="text-align:left;"><a href="./material-alpha-cutoff.html"><strong>alphaCutoff</strong></a></td><td style="text-align:left;">Alpha threshold used by <code>MASK</code> mode. Defaults to <code>0.5</code>.</td></tr><tr><td style="text-align:left;"><a href="./../../maths/vector3/vector3.html"><strong>Vector3</strong></a></td><td style="text-align:left;"><a href="./material-emissive-factor.html"><strong>emissiveFactor</strong></a></td><td style="text-align:left;">Additive linear-space RGB glow colour. Defaults to <code>(0, 0, 0)</code>.</td></tr><tr><td style="text-align:left;"><a href="./../texture/texture.html"><strong>Texture</strong></a></td><td style="text-align:left;"><a href="./material-base-color-texture.html"><strong>baseColorTexture</strong></a></td><td style="text-align:left;">Albedo texture multiplied with <code>baseColorFactor</code>. Empty by default.</td></tr><tr><td style="text-align:left;"><a href="./../texture/texture.html"><strong>Texture</strong></a></td><td style="text-align:left;"><a href="./material-emissive-texture.html"><strong>emissiveTexture</strong></a></td><td style="text-align:left;">Emission texture multiplied with <code>emissiveFactor</code>. Empty by default.</td></tr><tr><td style="text-align:left;"><a href="./../texture/texture.html"><strong>Texture</strong></a></td><td style="text-align:left;"><a href="./material-metallic-roughness-texture.html"><strong>metallicRoughnessTexture</strong></a></td><td style="text-align:left;">Packed metallic (B) / roughness (G) texture. Empty by default.</td></tr><tr><td style="text-align:left;"><a href="./../texture/texture.html"><strong>Texture</strong></a></td><td style="text-align:left;"><a href="./material-occlusion-texture.html"><strong>occlusionTexture</strong></a></td><td style="text-align:left;">Baked ambient-occlusion texture (R channel). Empty by default.</td></tr><tr><td style="text-align:left;"><a href="./../texture/texture.html"><strong>Texture</strong></a></td><td style="text-align:left;"><a href="./material-normal-texture.html"><strong>normalTexture</strong></a></td><td style="text-align:left;">Tangent-space normal map. Empty by default.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/int" target="_blank" rel="noreferrer"><strong>int</strong></a></td><td style="text-align:left;"><a href="./material-base-color-tex-coord.html"><strong>baseColorTexCoord</strong></a></td><td style="text-align:left;">UV set sampled by <code>baseColorTexture</code> (<code>0</code> or <code>1</code>). Defaults to <code>0</code>.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/int" target="_blank" rel="noreferrer"><strong>int</strong></a></td><td style="text-align:left;"><a href="./material-metallic-roughness-tex-coord.html"><strong>metallicRoughnessTexCoord</strong></a></td><td style="text-align:left;">UV set sampled by <code>metallicRoughnessTexture</code>. Defaults to <code>0</code>.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/int" target="_blank" rel="noreferrer"><strong>int</strong></a></td><td style="text-align:left;"><a href="./material-occlusion-tex-coord.html"><strong>occlusionTexCoord</strong></a></td><td style="text-align:left;">UV set sampled by <code>occlusionTexture</code>. Defaults to <code>0</code>.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/int" target="_blank" rel="noreferrer"><strong>int</strong></a></td><td style="text-align:left;"><a href="./material-emissive-tex-coord.html"><strong>emissiveTexCoord</strong></a></td><td style="text-align:left;">UV set sampled by <code>emissiveTexture</code>. Defaults to <code>0</code>.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/int" target="_blank" rel="noreferrer"><strong>int</strong></a></td><td style="text-align:left;"><a href="./material-normal-tex-coord.html"><strong>normalTexCoord</strong></a></td><td style="text-align:left;">UV set sampled by <code>normalTexture</code>. Defaults to <code>0</code>.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/w/cpp/string/basic_string" target="_blank" rel="noreferrer"><strong>std::string</strong></a></td><td style="text-align:left;"><a href="./material-name.html"><strong>name</strong></a></td><td style="text-align:left;">Human-readable material identifier, usually set by model loading. Defaults to <code>&quot;&quot;</code>.</td></tr></tbody></table><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to &quot;Constructors&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Arguments</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"></td><td style="text-align:left;">Default-constructs a white, fully metallic, medium-cutout PBR material with no textures and <code>alphaMode</code> set to <code>AUTO</code>.</td></tr></tbody></table><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Result</th><th style="text-align:left;">Method</th><th style="text-align:left;">Arguments</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/bool" target="_blank" rel="noreferrer"><strong>bool</strong></a></td><td style="text-align:left;"><a href="./material-operator-equal.html"><strong>operator ==</strong></a></td><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/const" target="_blank" rel="noreferrer"><strong>const</strong></a> <a href="./material.html"><strong>Material&amp;</strong></a> other</td><td style="text-align:left;">Compares every factor, texture, UV set, alpha mode, and name for equality.</td></tr><tr><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/bool" target="_blank" rel="noreferrer"><strong>bool</strong></a></td><td style="text-align:left;"><a href="./material-operator-not-equal.html"><strong>operator !=</strong></a></td><td style="text-align:left;"><a href="https://en.cppreference.com/cpp/keyword/const" target="_blank" rel="noreferrer"><strong>const</strong></a> <a href="./material.html"><strong>Material&amp;</strong></a> other</td><td style="text-align:left;">Returns <code>true</code> when any field differs from <code>other</code>.</td></tr></tbody></table><hr><p>Found an issue? <a href="https://github.com/JordanGrant3D/doriax-jord-docs/issues" target="_blank" rel="noreferrer">Report it here</a>.</p>',13)])])}const m=e(o,[["render",s]]);export{g as __pageData,m as default};
